custom.expression:
let tube = p * vec2<f32>(1.16, 2.0);
let q = p * (1.0 + 0.047 * dot(tube, tube));
let glass = sd_box(q, vec2<f32>(0.83, 0.445)) - 0.018;
let face = 1.0 - smoothstep(-0.002, 0.003, glass);
let row = floor(q.y * 225.0);
let roll = fract(q.y * 0.91 - t / 12.0);
let sync = exp(-90.0 * abs(roll - 0.35));
let jitter = hash(vec2<f32>(row, floor(t * 12.0))) - 0.5;
let v = q + vec2<f32>(jitter * (0.0009 + 0.006 * sync), 0.0);
let rally = t / 3.0 + 0.22;
let bx = (1.0 - 2.0 * abs(fract(rally * 0.5) * 2.0 - 1.0)) * 0.717;
let by = (1.0 - 2.0 * abs(fract(rally * 0.375 + 0.13) * 2.0 - 1.0)) * 0.344;
let left = by * (0.78 - 0.22 * bx / 0.717) + 0.058 * sin(rally * 3.14159);
let right = by * (0.78 + 0.22 * bx / 0.717) - 0.047 * sin(rally * 3.14159);
let bat = min(sd_box(v - vec2<f32>(-0.74, left), vec2<f32>(0.011, 0.068)), sd_box(v - vec2<f32>(0.74, right), vec2<f32>(0.011, 0.068)));
let ball = sd_box(v - vec2<f32>(bx, by), vec2<f32>(0.012));
let net = sd_box(vec2<f32>(v.x, (fract(v.y * 22.0 + 0.5) - 0.5) / 22.0), vec2<f32>(0.003, 0.012));
let zero = abs(sd_box(vec2<f32>(abs(v.x) - 0.095, v.y - 0.338), vec2<f32>(0.019, 0.029))) - 0.004;
let ch = v - vec2<f32>(0.718, 0.367);
let bars = sd_box(vec2<f32>(ch.x, min(abs(ch.y), abs(abs(ch.y) - 0.023))), vec2<f32>(0.015, 0.0027));
let three = min(bars, sd_box(ch - vec2<f32>(0.013, 0.0), vec2<f32>(0.0025, 0.023)));
let game = min(min(ball, bat), zero);
let raster = 0.86 + 0.14 * cos(v.y * 1413.717);
let grain = hash(floor(v * vec2<f32>(410.0, 225.0)) + vec2<f32>(floor(t * 15.0), 0.0));
let field = mix(c1, c2, clamp(0.54 - 0.32 * dot(tube, tube) + 0.09 * sin(v.y * 8.0 - t * 0.21) + grain * 0.08, 0.0, 1.0));
let smear = c4 * 0.48 * exp(-max(game, 0.0) * 106.0);
let phosphor = mix(field + smear, c3, fill(game));
let picture = mix(mix(phosphor, c5 * 0.72, fill(net)), c5, fill(three));
let color = mix(c1 * (0.48 + 0.32 * exp(-abs(glass) * 52.0)), picture * raster * (1.0 - 0.18 * sync), face);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);
